from __future__ import annotations
import hashlib,json,uuid
from pathlib import Path
from typing import Any
ROOT=Path(__file__).resolve().parents[2];POLICY=ROOT/"contracts/synthetic-remediation-execution-policy.json";DESTINATION=Path(__file__).with_name("remediation-scenarios.json")
NAMESPACE=uuid.UUID("3b6927f7-43e6-5d35-a04a-fd06bf7d2bef");SOURCES=("outlook-incidents.json","printer-incidents.json","scanner-incidents.json","windows-network-incidents.json")
OUTCOMES=("success","precondition_failed","execution_failed_no_change","partial_rollback_success","partial_rollback_failed","timeout_compensated","duplicate_idempotent_replay")
def digest(v:Any)->str:return hashlib.sha256(json.dumps(v,sort_keys=True,separators=(",",":"),ensure_ascii=False).encode()).hexdigest()
def build()->dict[str,Any]:
 policy=json.loads(POLICY.read_text());cases=[]
 for source in SOURCES:
  domain="windows_network" if source.startswith("windows") else source.split("-")[0];cases.extend((domain,c) for c in json.loads((ROOT/"data/synthetic"/source).read_text())["cases"])
 scenarios=[]
 for index,(domain,case) in enumerate(cases):
  outcome=OUTCOMES[index%len(OUTCOMES)];scenario_id=str(uuid.uuid5(NAMESPACE,f"{policy['seed']}:{case['case_id']}:{outcome}"));idempotency_key=str(uuid.uuid5(NAMESPACE,f"idempotency:{case['case_id']}:{case['safe_remediation']}"));pre_digest=case["device_state"]["baseline_digest"]
  changed=outcome in {"success","partial_rollback_success","partial_rollback_failed","timeout_compensated"};rollback_attempted=outcome in {"partial_rollback_success","partial_rollback_failed","timeout_compensated"};rollback_verified=outcome in {"partial_rollback_success","timeout_compensated"}
  terminal={"success":"resolved","precondition_failed":"unchanged","execution_failed_no_change":"unchanged","partial_rollback_success":"rolled_back","partial_rollback_failed":"escalated","timeout_compensated":"rolled_back","duplicate_idempotent_replay":"resolved"}[outcome]
  result_digest=digest({"scenario":scenario_id,"action":case["safe_remediation"],"outcome":outcome});post_digest=pre_digest if terminal in {"unchanged","rolled_back"} else result_digest
  attempts=[{"attempt":1,"status":"success" if outcome=="success" else "precondition_failed" if outcome=="precondition_failed" else "failure" if outcome=="execution_failed_no_change" else "partial" if outcome.startswith("partial") else "timeout" if outcome=="timeout_compensated" else "idempotent_replay","duration_ms":200+(index%9000),"state_changed":changed,"result_digest":result_digest,"safe_error":None if outcome in {"success","duplicate_idempotent_replay"} else {"code":outcome.upper(),"retryable":outcome in {"execution_failed_no_change","timeout_compensated"},"stack_trace_included":False}}]
  if outcome=="duplicate_idempotent_replay":attempts.append({"attempt":2,"status":"deduplicated","duration_ms":5,"state_changed":False,"result_digest":result_digest,"safe_error":None})
  rollback={"required":rollback_attempted,"attempted":rollback_attempted,"action":case["rollback"],"status":"verified" if rollback_verified else "failed" if outcome=="partial_rollback_failed" else "not_required","expected_pre_state_digest":pre_digest,"observed_post_rollback_digest":pre_digest if rollback_verified else post_digest,"verification_passed":rollback_verified}
  scenarios.append({"scenario_id":scenario_id,"seed":case["seed"],"tenant_id":policy["tenant_id"],"incident_case_id":case["case_id"],"incident_id":case["incident_id"],"endpoint_id":case["endpoint"]["id"],"domain":domain,"outcome":outcome,"plan":{"plan_id":str(uuid.uuid5(NAMESPACE,f"plan:{scenario_id}")),"typed_action_id":f"{domain}.{case['safe_remediation']}","arguments":{"target_id":case["endpoint"]["id"]},"risk_level":case["risk_level"],"authorization_ref":str(uuid.uuid5(NAMESPACE,f"authorization:{scenario_id}")),"authorization_valid":True,"precondition_digest":pre_digest,"rollback":case["rollback"],"maximum_attempts":policy["maximum_attempts"],"timeout_ms":policy["maximum_duration_ms"]},"idempotency_key":idempotency_key,"attempts":attempts,"rollback_result":rollback,"final_state":{"terminal_state":terminal,"pre_state_digest":pre_digest,"post_state_digest":post_digest,"change_retained":terminal=="resolved","safe_escalation_required":terminal=="escalated"},"verification":{"technical_check":case["verification"],"business_function_checked":True,"employee_confirmation_required":terminal=="resolved","passed":terminal=="resolved"},"evidence_lineage":{"plan_digest":digest({"action":case["safe_remediation"],"pre":pre_digest}),"attempt_result_digests":[a["result_digest"] for a in attempts],"audit_event_id":str(uuid.uuid5(NAMESPACE,f"audit:{scenario_id}"))},"replay":{"generator_version":"1.0.0","master_seed":policy["seed"],"source_case_seed":case["seed"],"sequence":index}})
 payload={"schema_version":"1.0.0","synthetic_only":True,"tenant_id":policy["tenant_id"],"seed":policy["seed"],"scenario_count":len(scenarios),"scenarios":scenarios};payload["dataset_digest"]=digest(payload);return payload
def canonical_bytes()->bytes:return (json.dumps(build(),sort_keys=True,separators=(",",":"),ensure_ascii=False)+"\n").encode()
if __name__=="__main__":DESTINATION.write_bytes(canonical_bytes());print(DESTINATION)
